css:
/* ====== Reusable component — all rules scoped under .uiv-fan-card ( use image instead of svg) ====== */
.uiv-fan-card {
  --accent: #161614;
  --muted: #5a5a56;
  --faint: #8a8a84;
  --line: #d8d6cd;
  --w: 240px;

  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 20px;
  padding: 24px;
  font-family: "Segoe UI", Helvetica, Arial, sans-serif;
  transition: background 0.3s ease;
}

.uiv-fan-card .card {
  width: var(--w);
  color: var(--accent);
  padding: 18px 16px 0;
  border-left: 1px solid var(--line);
  cursor: pointer;
  transition:
    color 0.3s ease,
    border-color 0.3s ease;
}

.uiv-fan-card .badge {
  display: inline-block;
  border: 1px solid var(--accent);
  color: var(--accent);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 1px 6px;
  margin-bottom: 16px;
}

.uiv-fan-card .dates {
  font-size: 10.5px;
  color: var(--faint);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin: 0 0 10px;
}

.uiv-fan-card .title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.22;
  letter-spacing: -0.005em;
  margin: 0 0 8px;
}

.uiv-fan-card .desc {
  font-size: 12.5px;
  color: var(--muted);
  line-height: 1.45;
  margin: 0 0 22px;
}

.uiv-fan-card .stack {
  position: relative;
  height: 128px;
  margin: 22px 0 6px;
  overflow: visible;
}

.uiv-fan-card .stack .sheet,
.uiv-fan-card .stack .art {
  position: absolute;
  inset: 0;
  overflow: hidden;
  transform-origin: 0% 100%;
  transition:
    transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 0.45s ease;
}

.uiv-fan-card .stack img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.uiv-fan-card .stack .sheet:nth-child(1) {
  transform: rotate(3.5deg);
  opacity: 0.8;
}
.uiv-fan-card .stack .sheet:nth-child(2) {
  transform: rotate(7deg);
  opacity: 0.6;
}
.uiv-fan-card .stack .sheet:nth-child(3) {
  transform: rotate(10.5deg);
  opacity: 0.4;
}
.uiv-fan-card .stack .sheet:nth-child(4) {
  transform: rotate(14deg);
  opacity: 0.25;
}
.uiv-fan-card .stack .art {
  transform: rotate(0deg);
}

/* hover: fan opens wider */
.uiv-fan-card .card:hover .stack .sheet:nth-child(1) {
  transform: rotate(7deg);
}
.uiv-fan-card .card:hover .stack .sheet:nth-child(2) {
  transform: rotate(14deg);
}
.uiv-fan-card .card:hover .stack .sheet:nth-child(3) {
  transform: rotate(21deg);
}
.uiv-fan-card .card:hover .stack .sheet:nth-child(4) {
  transform: rotate(28deg);
}
.uiv-fan-card .card:hover .stack .art {
  transform: rotate(-3deg);
}
/* ====== end component ====== */
